import sys
from collections import defaultdict, deque

def read_ints():
    return list(map(int, sys.stdin.readline().strip().split()))

n, m, k, s = read_ints()
goods_types = read_ints()
roads = [read_ints() for _ in range(m)]

# Create adjacency list for the graph
adj_list = defaultdict(list)
for u, v in roads:
    adj_list[u].append(v)
    adj_list[v].append(u)

# Function to compute shortest paths using BFS
def bfs(start):
    dist = [-1] * (n + 1)
    queue = deque([start])
    dist[start] = 0
    while queue:
        u = queue.popleft()
        for v in adj_list[u]:
            if dist[v] == -1:
                dist[v] = dist[u] + 1
                queue.append(v)
    return dist

# Compute the minimum expenses for each town
min_expenses = []
for i in range(1, n + 1):
    dist = bfs(i)
    min_cost = float('inf')
    for j in range(1, n + 1):
        if dist[j] != -1:
            cost = 0
            for town in range(1, n + 1):
                if dist[town] != -1 and goods_types[town - 1] != goods_types[i - 1]:
                    cost += dist[town]
            min_cost = min(min_cost, cost)
    min_expenses.append(min_cost)

# Output the result
print(' '.join(map(str, min_expenses)))
